describe('Footer Navigation Links', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should navigate to correct page when footer link is clicked', () => {
    // Verify footer is visible
    cy.get('[data-testid="footer-nav"]').should('be.visible');

    // Verify footer contains navigation links
    cy.get('[data-testid="footer-nav"]').should('contain', 'Home');
    cy.get('[data-testid="footer-nav"]').should('contain', 'About');
    cy.get('[data-testid="footer-nav"]').should('contain', 'Contact');

    // Click the Home link
    cy.get('[data-testid="footer-nav"]').find('[data-testid="nav-link-home"]').click();

    // Verify navigation occurred
    cy.url().should('include', '/');

    // Verify page title is correct
    cy.title().should('equal', 'Home');

    // Verify footer is still visible
    cy.get('[data-testid="footer-nav"]').should('be.visible');
  });

  it('should handle edge case when footer link is disabled', () => {
    // Verify footer is visible
    cy.get('[data-testid="footer-nav"]').should('be.visible');

    // Verify disabled link is present
    cy.get('[data-testid="footer-nav"]').find('[data-testid="nav-link-contact"]').should('be.visible');

    // Verify disabled link has appropriate class
    cy.get('[data-testid="nav-link-contact"]').should('have.class', 'disabled');

    // Verify disabled link is not clickable
    cy.get('[data-testid="nav-link-contact"]').should('not.be.visible');

    // Verify other links are clickable
    cy.get('[data-testid="nav-link-home"]').click();
    cy.url().should('include', '/');

    // Verify footer is still visible
    cy.get('[data-testid="footer-nav"]').should('be.visible');
  });
});
